INSERT INTO `risks` VALUES (1,'快件无序堆放占用消防疏散通道',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'作业期间需划定固定的消防通道，通道内严禁堆放任何快件及杂物，班组人员每两小时开展一次巡查，发现占用情况立即清理，保障通道全程保持畅通，满足应急疏散需求，同时定期组织员工熟悉疏散路线，避免突发情况时慌乱拥堵。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(2,'电动三轮车在网点室内及封闭区域充电',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'所有派送车辆需转移至室外专用充电区域充电，配备符合安全标准的阻燃充电桩，禁止私拉乱接非专用电线充电，充电过程安排专人值守，充满后及时切断电源，杜绝无人值守过夜充电，充电区域周边严禁堆放易燃包装材料。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(3,'快递三轮车超速行驶、违反交通信号通行',NULL,NULL,3,6,9,162,'橙色','已评审',NULL,'为全部电动三轮车加装固定限速装置，限定最高行驶速度不超过规定限值，定期组织派送人员开展交通安全专项培训，结合行业典型事故案例强化规则意识，路面安排管理人员巡查监督，对违规行为依规严肃处理，屡教不改者暂停上岗培训。',NULL,'公司级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(4,'装卸快件过程中抛扔、踩踏快件',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'作业前向操作人员明确装卸规范，要求轻拿轻放各类快件，严禁抛扔、踩踏、拖拽行为，班组管理人员全程现场监护，发现违规操作及时制止，并现场示范正确操作方式，同时将快件破损率纳入日常考核，倒逼规范作业。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(5,'人工搬运快件姿势不当造成肢体扭伤',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'操作人员需提前掌握正确的搬运姿势，起身时依靠腿部发力支撑，避免直接弯腰负重搬运，较重或体积较大快件安排双人协同搬运，合理控制连续作业时长，中途定时休息放松，防止因过度劳累引发肢体拉伤、扭伤等损伤。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(6,'网点地面湿滑未设置警示标识',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'地面出现水渍、油污、雨雪积水后及时清理干净，清理完成前全程铺设防滑垫，在周边放置醒目防滑警示标识，提醒往来员工及客户注意避让，待地面完全干燥后再移除相关防护设施，避免人员滑倒摔伤。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(7,'网点内私拉乱接电气线路，线路外皮破损裸露',NULL,NULL,3,4,7,84,'黄色','已评审',NULL,'电气线路布设必须由专业持证电工操作，严禁非专业人员私自搭接、改装线路，定期对所有线路进行全面排查，发现破损、老化情况立即更换，禁止使用普通绝缘胶带简单缠绕应急，确保线路绝缘性能达标。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(8,'插排串联使用、超负荷接电运行',NULL,NULL,3,4,7,84,'黄色','已评审',NULL,'单个插排仅允许接入额定功率范围内的用电设备，严禁多个插排首尾串联使用，大功率电器单独配置专用固定插座，每日下班前安排专人排查用电情况，当场拆除违规串联的插排，杜绝超负荷用电隐患。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(9,'消防灭火器过期失效、压力值不达标',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'每月对网点所有灭火器进行逐一逐项检查，核对有效期与压力表状态，过期或压力不足的器材立即更换补充，将灭火器放置在显眼易取用的位置，严禁遮挡掩埋，同步开展实操使用培训，确保员工会用、能用。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(10,'室内消火栓被遮挡、内部缺水或缺配件',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'消火栓周边1米范围内禁止堆放任何快件、杂物及设备，每月开箱检查水压、水带、接口及配件完整性，发现故障或缺失情况立即报修维护，确保火灾发生时可快速取用、正常投入使用。',NULL,'转运中心级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(11,'网点门窗破损、防盗设施失效',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'每日上下班前安排专人检查门窗及防盗设施完整性，破损的玻璃、门锁、防盗链及时维修更换，下班前确保所有门窗关闭并反锁到位，根据网点实际需求加装简易防盗装置，防范夜间财物及快件被盗风险。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(12,'监控设备故障、作业区域存在监控死角',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'优化监控点位布局，实现作业、分拣、装卸、仓储区域全覆盖无死角，每日查看监控画面清晰度与运行状态，故障设备24小时内完成维修更换，监控录像留存时长不低于30天，便于隐患溯源和事故核查。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(13,'易燃易爆违禁品未检出流入网点',NULL,NULL,3,3,15,135,'黄色','已评审',NULL,'收件环节严格执行开箱验视和实名收寄制度，对粉末、液体、不明气味、异形包装物品重点核查，定期组织员工开展违禁品识别专项培训，发现可疑物品立即暂扣并上报，严禁违规转运或派送。',NULL,'转运中心级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(14,'液体快件破损泄漏污染场地及其他快件',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'液体类快件单独分区存放，采用防渗漏、防挤压包装妥善封装，单独分拣和搬运，发生泄漏后立即转移至空旷通风区域，使用专用吸附材料清理泄漏物，避免污染扩散及人员滑倒受伤，同时隔离受污染快件妥善处理。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(15,'网点内违规吸烟、使用明火',NULL,NULL,3,1,15,45,'蓝色','已评审',NULL,'网点全域划定为禁烟禁火区域，张贴醒目禁烟警示标识，安排专人不定时流动巡查，严禁携带火种进入作业区，对违规吸烟行为从严处理，通过监控全程监督管控，同时在网点外设置指定吸烟点，引导员工规范行为。',NULL,'公司级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(16,'扫码设备、办公电器漏电引发触电',NULL,NULL,2,4,3,24,'蓝色','已评审',NULL,'每日使用前检查设备外壳及电源线路完整性，做好接地防护措施，发现漏电、麻手情况立即停止使用，交由专业人员维修处理，严禁非专业人员私自拆解设备，避免触电事故发生。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(17,'打包机运转时夹手、皮带划伤肢体',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'打包机需安装完整防护挡板和急停装置，严禁擅自拆除防护部件，运转过程中禁止将手伸入运转区域，设备卡滞时先切断电源停机再处理，禁止开机状态下掏取杂物，操作时保持安全距离。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(18,'胶带切割机使用不当割伤手指',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'操作胶带切割机时保持手指与刀片安全距离，缓慢拉动胶带完成切割，避免快速用力操作，刀片钝化后及时更换专用刀片，不用时将刀片收回防护壳内，规范存放避免随意摆放，防止误触割伤。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(19,'分拣区域人员过于密集引发碰撞摔倒',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'划分单人固定作业区域，控制同一区域内作业人数，避免人员扎堆拥挤，作业人员行走时放缓速度，禁止推搡、打闹、奔跑，人流高峰时段分批开展分拣作业，保障现场秩序稳定。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(20,'夏季高温天气网点无通风降温措施',NULL,NULL,2,4,3,24,'蓝色','已评审',NULL,'高温时段开启大功率通风及降温设备，保证室内空气流通顺畅，为员工提供防暑饮品、藿香正气水等防暑药品，避开正午高温时段开展高强度户外作业，员工出现头晕、恶心等不适症状立即安排休息。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(21,'雨雪天气网点入口无防滑防护措施',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'在网点入口处连续铺设多层防滑垫，及时清扫门口积雪与积水，设置醒目防滑提示标识，提醒员工及客户缓慢通行，避免因地面湿滑发生摔倒意外，同时准备干毛巾方便人员擦拭鞋底水渍。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(22,'作业人员未佩戴劳保手套、反光背心',NULL,NULL,2,4,3,24,'蓝色','已评审',NULL,'上岗前必须按要求佩戴防滑劳保手套，外出派送时全程穿戴反光背心，班组管理人员逐一核查佩戴情况，未按规定防护的人员禁止上岗作业，同时及时更换破损、脏污的防护用品。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(23,'客户隐私信息泄露、违规传播',NULL,NULL,1,3,7,21,'蓝色','已评审',NULL,'严格管控客户信息查阅权限，仅允许相关操作人员查看必要信息，严禁拍摄、转发、传播客户隐私信息，全员签订信息保密协议，对泄露信息的行为依规追究相关责任，情节严重者移交司法部门。',NULL,'公司级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(24,'快件错分、丢失引发服务纠纷',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'分拣时仔细核对快件目的地、收件人信息，扫码确认后规范分区存放，快件交接时双方签字核对数量和信息，完善流转记录，出现错分、丢失情况及时跟进溯源处理，降低客户投诉和纠纷发生率。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(25,'网点大门未及时关闭落锁导致快件被盗',NULL,NULL,1,3,7,21,'蓝色','已评审',NULL,'离开作业区域时随手关闭大门，非作业时段及时落锁，下班前安排专人检查所有出入口落锁情况，夜间定期巡查网点周边，联动安防监控设施，防范外来人员私自进入盗取快件。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(26,'无关人员及儿童随意进入作业区域',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'作业区域实行封闭式准入管理，外来人员需实名登记信息并由专人全程陪同，禁止儿童进入分拣、装卸、设备操作区域，发现无关人员及时劝阻并引导至客户等候区，避免干扰作业引发意外。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(27,'网点照明不足，夜间作业视线受限',NULL,NULL,2,4,3,24,'蓝色','已评审',NULL,'在作业盲区、角落增设照明灯具，损坏的灯管、灯泡及时更换，保证作业区域光线充足柔和，夜间装卸、分拣时全开所有照明设备，严禁在昏暗、局部照明条件下作业，防止视线不清引发失误。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(28,'网点垃圾长期堆积未及时清理',NULL,NULL,1,3,1,3,'蓝色','已评审',NULL,'网点内垃圾桶满溢后立即清理，做到日产日清，定期对垃圾存放区域进行消杀除味，保持网点环境卫生整洁，避免垃圾堆积滋生细菌、引发异味，同时分类处理废弃包装和生活垃圾，便于回收处置。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(29,'消杀药剂配比超标，人员吸入后身体不适',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'严格按照产品说明书配比消杀药剂，精准控制药剂浓度，避开人员密集、作业高峰时段开展消杀，消杀作业时佩戴口罩、手套等防护用品，消杀完成后开窗充分通风，减少药剂残留危害。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(30,'消杀设备漏电、喷杆划伤操作人员',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'使用消杀设备前检查机身及电源线路完整性，做好绝缘防护处理，喷杆边缘打磨光滑无毛刺，操作时规范握持喷杆，避免大幅度挥动造成划伤，设备用完后及时清理存放，防止漏电隐患。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(31,'快递柜故障夹人、漏电存在安全隐患',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'定期安排专业人员全面检修快递柜，故障设备立即暂停使用并张贴维修提示，安装紧急解锁装置，做好漏电防护措施，全面排查安全隐患后再恢复使用，同时在快递柜旁张贴安全使用提示。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(32,'上门派送快件时人员安全防范不足',NULL,NULL,2,6,7,84,'黄色','已评审',NULL,'外出派送前报备行程及目的地，全程保持通讯畅通，避开偏僻、复杂、治安差的区域，遇到异常客户或情况及时求助报备，提前熟悉应急联络方式，夜间派送尽量结伴而行，保障自身人身安全。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(33,'派送骑行时头盔佩戴不规范、未系绑带',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'骑行派送车辆必须规范佩戴安全头盔，系紧头盔绑带，确保贴合头部不松动，上岗前管理人员逐一核查佩戴情况，未规范佩戴的人员禁止出车，定期强调头盔防护的重要性，强化安全意识。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(34,'派送车辆违规停放占用消防通道',NULL,NULL,2,6,7,84,'黄色','已评审',NULL,'网点周边划定专用车辆停放区域，引导车辆有序停放，严禁占用消防通道及疏散路径，管理人员定期巡查停放情况，发现违规停放车辆及时挪移整改，同时对员工开展消防通道管控培训。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(35,'恶劣天气下强行派送引发安全事故',NULL,NULL,3,3,9,81,'黄色','已评审',NULL,'暴雨、大风、冰雪、大雾等恶劣天气减少外出派送，极端天气直接暂停作业，确需出行的放缓行驶速度，选择安全平坦路线，避开积水、结冰严重、易滑坡路段，确保出行安全。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(36,'网点安全台账记录缺失、填写不规范',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'建立完善的安全管理台账，如实记录隐患排查、培训、演练、整改等情况，安排专人负责台账整理归档，定期核查台账完整性和规范性，做到全程可追溯，杜绝台账造假、漏记。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(37,'网点消杀后场地未通风，药剂残留伤人',NULL,NULL,2,3,4,24,'蓝色','已评审',NULL,'完成场地全面消杀后，打开所有门窗充分通风换气，等待药剂气味完全消散后，再允许人员进入作业区域，避免人员长时间接触高浓度消杀药剂，防止呼吸道刺激或皮肤过敏。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(38,'快件堆放过高发生倾倒砸伤人员',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'严格限定快件堆放高度，遵循下重上轻、平稳堆放原则，底部铺垫稳固托盘，避免单侧倾斜、超高堆放，人员不在高堆快件下方停留、作业，定期整理堆放快件，防止重心不稳倾倒。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(39,'网点用电设备下班未断电，长期待机起火',NULL,NULL,3,4,8,96,'黄色','已评审',NULL,'每日下班前，安排专人逐一关闭所有用电设备电源，拔掉待机插头，杜绝设备长时间通电待机，定期排查待机用电隐患，防范电气线路过热引发火灾，同时养成人走断电的良好习惯。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(40,'客户取件时拥挤碰撞，发生意外受伤',NULL,NULL,2,5,4,40,'蓝色','已评审',NULL,'划定客户专属取件等候区域，设置隔离护栏，安排专人现场疏导，引导客户有序排队取件，避免人员拥挤碰撞，高峰时段分流取件，保障客户及员工人身安全，同时在等候区放置防滑垫和警示标识。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(41,'网点消防应急照明损坏，断电后无照明',NULL,NULL,2,3,6,36,'蓝色','已评审',NULL,'定期检查应急照明、疏散指示设备，损坏的及时更换，每月测试设备运行状态，保证断电后可正常亮起，亮度满足应急疏散照明需求，确保突发断电时人员能安全疏散。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(42,'派送车辆刹车灵敏度不足，行驶中失控',NULL,NULL,3,6,9,162,'橙色','已评审',NULL,'每日出车前全面检查车辆刹车系统，定期开展专业车辆维保，刹车灵敏度不达标立即维修更换，严禁车辆带病上路，保障行驶制动安全，同时培训员工正确刹车操作技巧。',NULL,'公司级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(43,'网点内堆放易燃易爆杂物引发火灾',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'及时清理网点内废弃纸箱、泡沫、胶带等易燃杂物，严禁在作业区、仓储区存放汽油、酒精等易燃易爆物品，杂物定点存放并及时清运，消除火灾隐患源头。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(44,'员工湿手触碰电源开关引发触电',NULL,NULL,2,4,3,24,'蓝色','已评审',NULL,'严禁员工湿手、沾水触碰电源开关、插座及用电设备，洗手后及时擦干手部，在电源区域张贴警示标识，培训员工基础用电安全知识，杜绝违规触碰行为。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(45,'快件分拣时误拿尖锐物品划伤手部',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'分拣快件时留意包裹形状，遇到尖锐边角、异形包裹轻拿轻放，佩戴加厚劳保手套，避免徒手直接触碰尖锐部位，发现破损尖锐快件单独隔离处理，防止划伤操作人员。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(46,'网点地面杂物散落绊倒作业人员',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'作业过程中及时清理地面散落的包装带、纸屑、胶带等杂物，保持作业通道畅通整洁，严禁随意丢弃杂物，班组人员定时巡查地面，发现杂物立即清理，避免人员行走时绊倒受伤。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(47,'冬季网点取暖器近距离烘烤快件起火',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'冬季取暖器远离快件、包装等易燃物品，保持安全距离，严禁用取暖器烘烤衣物、快件，安排专人看管取暖设备，离开时及时关闭电源，防止烘烤过热引发火灾。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(48,'客户寄递物品未验视导致违禁品流入',NULL,NULL,3,3,15,135,'黄色','已评审',NULL,'严格执行寄递物品百分百验视制度，所有寄件必须开箱检查，无包装物品现场封装查验，拒绝寄递不明物品、违禁物品，对不配合验视的客户坚决不予收件，从源头阻断违禁品流入。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(49,'网点消防通道标识模糊不清不易辨识',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'重新涂刷消防通道标识线，更换清晰醒目的疏散指示牌，定期清理标识上的灰尘污渍，确保标识清晰可见，让员工和客户快速辨识疏散通道，避免应急时找不到疏散路径。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(50,'办公区域电线杂乱缠绕引发短路',NULL,NULL,2,4,5,40,'蓝色','已评审',NULL,'整理办公区域所有电线、网线，使用理线器固定，避免杂乱缠绕、挤压，远离高温设备和尖锐物品，定期检查线路状态，防止缠绕过热引发短路，规范办公用电环境。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(51,'员工搬运快件时重心不稳摔倒',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'搬运快件时保持身体重心平稳，量力而行搬运合适重量，避免单手负重、侧身行走，地面湿滑时放慢脚步，多人协同搬运时配合默契，防止重心不稳摔倒受伤。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(52,'网点周边排水不畅雨天积水影响通行',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'提前疏通网点周边排水管道，清理排水口杂物，雨天及时清扫积水，在积水区域铺设防滑垫，设置警示标识，保障员工和客户通行安全，避免积水浸泡网点设施。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(53,'扫码设备摔落损坏影响作业进度',NULL,NULL,2,4,3,24,'蓝色','已评审',NULL,'操作人员手持扫码设备时握紧防滑，放置在固定工位时摆放平稳，避免随意放在桌边、高台边缘，防止摔落损坏，备用一台扫码设备，故障时及时替换，保障作业不间断。',NULL,'岗位级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(54,'废弃电池违规丢弃污染环境伤人',NULL,NULL,1,3,5,15,'蓝色','已评审',NULL,'设立专用废弃电池回收箱，分类回收废旧扫码器、车辆电池，严禁随意丢弃混入生活垃圾，定期交由专业机构处置，防止电池漏液污染环境或腐蚀人体皮肤。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(55,'员工在作业区域追逐嬉闹引发意外',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'严禁员工在分拣、装卸、通道等作业区域追逐、嬉闹、奔跑，管理人员现场监督制止，加强员工行为规范教育，营造有序作业氛围，避免嬉闹引发碰撞、摔倒意外。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(56,'快件包装破损未及时处理导致内件丢失',NULL,NULL,2,3,5,30,'蓝色','已评审',NULL,'分拣时发现包装破损快件，立即停止流转，使用专用包装材料重新封装，登记破损信息，核对内件完整性，避免内件丢失或污染，同时上报破损情况跟进处理。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(57,'网点消防沙箱缺失、未及时补充',NULL,NULL,1,3,4,12,'蓝色','已评审',NULL,'按规范配备消防沙箱，放置在显眼位置，箱内沙土保持干燥足量，定期检查补充，用于扑救初期油类、电气火灾，确保应急时可快速取用。',NULL,'部门级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(58,'员工长时间低头分拣引发颈椎不适',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'合理调整分拣工作台高度，提醒员工定时抬头活动颈椎，避免长时间保持同一低头姿势，安排间歇休息，缓解颈部疲劳，关注员工职业健康，减少慢性劳损。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(59,'网点大门玻璃破损未及时更换割伤人',NULL,NULL,1,3,4,12,'蓝色','已评审',NULL,'每日检查网点大门玻璃完整性，发现破损、裂纹立即更换，避免玻璃碎裂割伤人员，在玻璃门张贴防撞标识，提醒人员缓慢通行，防止碰撞破损。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(60,'客户寄递易碎品未做特殊标注导致破损',NULL,NULL,2,3,5,30,'蓝色','已评审',NULL,'客户寄递易碎品时，主动提醒做好防碎包装，粘贴醒目易碎警示标识，分拣、搬运时单独处理，轻拿轻放，避免堆叠挤压，降低快件破损概率，提升客户满意度。',NULL,'班组级',NULL,'网点','作业现场','2026-07-01 11:52:36'),(61,'新员工未接受安全培训直接上岗',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'新员工入职后，先开展岗位安全及操作规范专项培训，覆盖消防、用电、设备操作、违禁品识别等内容，考核合格后再安排上岗，安排老员工一对一帮带，帮助新员工熟悉作业流程及安全注意事项。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(62,'员工违规操作机械设备引发事故',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'将各设备操作规程张贴在作业区域显眼位置，要求员工严格按流程规范操作，管理人员现场监督纠正违规行为，对违规人员重新开展操作培训，考核合格后方可再次上岗。',NULL,'岗位级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(63,'员工连续超时作业，过度疲劳引发失误',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'合理安排员工排班表，控制每日作业时长，保证员工充足休息时间，避免连续超负荷、超时长作业，发现员工出现疲劳乏力、精神萎靡状态，及时安排轮岗休息，严禁强令疲劳作业。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(64,'员工酒后上岗、情绪异常开展作业',NULL,NULL,3,1,15,45,'蓝色','已评审',NULL,'上岗前管理人员观察员工精神状态，排查饮酒、情绪过激、状态异常人员，发现此类人员立即禁止上岗，做好心理疏导和安抚工作，建立奖惩机制，杜绝违规上岗行为。',NULL,'公司级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(65,'员工突发身体疾病，现场无应急处置措施',NULL,NULL,1,3,7,21,'蓝色','已评审',NULL,'网点配备标准急救箱及常用急救药品，组织员工学习基础急救知识和操作方法，员工突发疾病时，立即停止其作业，采取科学应急处置措施，必要时联系医疗机构救助，同时上报公司。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(66,'员工之间发生争执，引发肢体冲突',NULL,NULL,1,2,7,14,'蓝色','已评审',NULL,'管理人员第一时间介入调解员工矛盾，耐心沟通化解分歧，维护现场作业秩序，加强员工文明作业和团结教育，避免矛盾激化，营造和谐稳定的作业氛围。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(67,'特种作业人员无证操作相关设备',NULL,NULL,2,3,15,90,'黄色','已评审',NULL,'特种作业岗位必须安排持证上岗人员，定期核查证件有效期，组织持证人员参加复审培训，严禁无证人员违规操作特种设备、特种车辆，发现违规行为严肃处理。',NULL,'转运中心级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(68,'作业前安全交底不到位，违章指挥作业',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'每日作业前开展班前安全交底，明确当日作业重点、风险点及防控注意事项，全员确认知晓后签字记录，严禁管理人员违章指挥、强令员工冒险作业，员工有权拒绝违规指挥。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(69,'未定期开展应急演练，员工无逃生技能',NULL,NULL,1,2,15,30,'蓝色','已评审',NULL,'每季度组织一次消防、应急疏散类实战演练，覆盖所有在岗员工，讲解应急逃生路线、自救互救方法，演练后总结问题，优化应急流程，全面提升员工应急处置能力。',NULL,'公司级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(70,'员工不会操作消防器材，应急处置能力弱',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'定期开展消防器材实操培训，现场演示灭火器、消火栓使用方法和步骤，确保每位员工都能独立熟练操作，定期复训巩固，应对突发火灾时可快速有效处置。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(71,'员工违禁品识别能力不足，漏检风险高',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'每月开展违禁品识别专项培训，结合实物案例、图片讲解各类违禁品特征，提升员工辨别能力，考核通过后方可参与收件验视、分拣工作，降低违禁品漏检概率。',NULL,'转运中心级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(72,'员工交通安全培训缺失，违规骑行频发',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'每月组织全员交通安全专题培训，讲解道路行驶规则、避险技巧和行业事故案例，强化员工道路安全意识，减少超速、逆行、闯红灯等违规骑行行为。',NULL,'公司级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(73,'员工用电安全知识不足，违规操作电器',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'开展用电安全专项讲解培训，告知员工违规用电的危害和后果，禁止湿手触碰电源及电器，规范插拔插头，让员工掌握基础用电隐患识别和应急处置方法。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(74,'员工消防安全意识淡薄，忽视火灾隐患',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'通过日常宣传、案例讲解、张贴警示海报等方式，强化员工消防安全意识，提醒员工留意身边火灾隐患，养成随手清理易燃物、人走断电的良好习惯。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(75,'员工职业健康防护不到位，引发职业病',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'足额发放合格劳动防护用品，定期组织员工开展职业健康体检，改善作业环境通风、降噪、除尘条件，降低粉尘、噪音、久坐等危害，保障员工长期职业健康。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(76,'员工心理压力过大，未开展疏导关怀',NULL,NULL,1,2,3,6,'蓝色','已评审',NULL,'关注员工日常心理状态，定期开展心理疏导及人文关怀活动，缓解工作和生活压力，建立畅通沟通渠道，及时倾听员工诉求，帮助解决实际困难，稳定员工队伍。',NULL,'公司级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(77,'岗位操作规程未张贴，员工无章可循',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'将各岗位操作规程打印装订，张贴在对应作业区域显眼处，方便员工随时查看学习，组织全员系统学习规程内容，要求严格按照规程开展作业，杜绝无章操作。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(78,'现场违章作业无人制止，监管缺位',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'明确现场安全监管责任，管理人员及老员工均有制止违章作业的义务，发现违规行为立即叫停整改，形成全员监督、互相提醒的良好氛围，杜绝违章作业蔓延。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(79,'劳动防护用品发放不及时，员工无防护用具',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'根据岗位实际需求足额配备防护用品，建立规范发放台账，及时为员工补发破损、缺失、过期的防护用品，确保上岗员工都有合格有效的防护用具。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(80,'防护用品破损失效，未及时更换',NULL,NULL,2,3,3,18,'蓝色','已评审',NULL,'员工日常上岗前检查防护用品完好状态，发现破损、失效、脏污情况，及时上报申请更换，严禁使用不合格防护用品上岗，班组定期核查防护用品完好性。',NULL,'岗位级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(81,'员工带病坚持作业，加重身体不适',NULL,NULL,1,3,7,21,'蓝色','已评审',NULL,'上岗前主动询问员工身体状况，发现身体不适、生病人员，强制安排休息或就医，严禁员工带病坚持作业，避免因身体虚弱引发操作失误或加重病情。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(82,'外来人员无登记进入网点，管理混乱',NULL,NULL,1,3,7,21,'蓝色','已评审',NULL,'外来人员进入网点需实名登记信息、查验来意，由内部人员全程陪同进入指定区域，严禁无关人员随意穿行作业区域，严防外来人员触碰设备、翻动快件。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(83,'岗位交接班记录缺失，问题未交接',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'执行规范的岗位交接班流程，书面记录当班问题、未完成事项及安全注意事项，交接双方签字确认，确保问题闭环交接，避免因交接不清引发后续隐患和工作失误。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(84,'隐患排查流于形式，问题未整改闭环',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'定期开展全方位、无死角隐患排查，建立隐患整改台账，明确整改时限、责任人及整改措施，整改完成后专人复查销号，形成排查、整改、复查的闭环管理。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(85,'岗位风险告知不到位，员工不知情',NULL,NULL,1,3,3,9,'蓝色','已评审',NULL,'制作岗位风险告知卡，上岗前向员工清晰告知岗位风险、防控措施及应急方法，张贴在作业区域显眼处，确保员工全面知晓自身岗位安全风险，提高自我防范意识。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(86,'应急物资缺失、损坏，无法投入使用',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'配齐消防、急救、疏散类应急物资，安排专人专项管理，定期检查物资完好性、有效期，损坏、缺失、过期的物资及时补充更换，保证突发情况时可正常使用。',NULL,'转运中心级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(87,'员工违规攀爬快件堆垛，引发坠落',NULL,NULL,2,4,6,48,'蓝色','已评审',NULL,'严禁员工攀爬快件堆垛、货架登高取件，提醒员工远离高堆快件区域，现场管理人员及时制止攀爬行为，详细讲解此类行为的安全风险，杜绝违规攀爬。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(88,'员工未参加定期安全复训，知识淡忘',NULL,NULL,1,3,5,15,'蓝色','已评审',NULL,'每半年组织一次全员安全复训，巩固安全操作、消防、应急知识，避免长时间不培训导致知识淡忘，复训后开展考核，确保员工熟练掌握各项安全技能。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(89,'员工对网点疏散路线不熟悉',NULL,NULL,1,3,5,15,'蓝色','已评审',NULL,'张贴清晰的疏散路线图，定期组织员工熟悉疏散路径，利用演练机会强化记忆，确保每位员工在突发情况下能快速找到安全出口，有序疏散。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(90,'员工擅自离岗脱岗导致现场无人监管',NULL,NULL,2,3,5,30,'蓝色','已评审',NULL,'严格执行岗位考勤制度，员工离岗需报备并找人顶岗，严禁擅自离岗、脱岗，确保每个作业岗位有人值守，避免现场无人监管引发快件丢失、设备故障等问题。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(91,'员工操作设备时注意力不集中玩手机',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'作业期间严禁员工玩手机、刷视频，要求全身心投入操作，管理人员现场监督，发现分心行为及时制止，避免注意力不集中引发设备操作失误或快件破损。',NULL,'岗位级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(92,'新员工操作设备无人监护引发失误',NULL,NULL,2,4,5,40,'蓝色','已评审',NULL,'新员工试用期内操作设备，必须有老员工全程监护指导，禁止单独操作设备，熟悉流程和技巧后再逐步独立作业，防止因操作不熟练引发安全事故。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(93,'员工不服从管理违规作业',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'加强员工制度教育，对不服从管理、执意违规作业的员工，先批评教育，再暂停上岗培训，屡教不改者按公司规章制度处理，维护现场安全管理秩序。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(94,'员工职业素养不足，粗暴对待快件',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'加强员工职业素养培训，树立爱护快件、服务客户的意识，杜绝粗暴对待快件，将快件完好率纳入考核，激励员工规范操作，提升服务质量。',NULL,'班组级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(95,'员工未掌握初期火灾扑救方法',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'专项培训初期火灾扑救技巧，明确不同火灾类型的扑救方式，让员工熟练使用消防器材，发现小火情能快速处置，防止火势扩大蔓延，减少损失。',NULL,'部门级',NULL,'网点','人员管理','2026-07-01 11:52:36'),(96,'电动三轮车刹车失灵、行驶跑偏',NULL,NULL,3,6,9,162,'橙色','已评审',NULL,'每日出车前全面检查车辆刹车系统、转向系统，定期做专业制动维保，刹车故障、行驶跑偏立即维修，严禁制动不合格车辆上路，保障行驶制动和转向安全。',NULL,'公司级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(97,'车辆轮胎破损、鼓包、漏气行驶',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'出车前仔细检查轮胎外观、胎压，破损、鼓包、漏气、磨损过度的轮胎及时更换，定期检查胎压标准值，避免轮胎带病运行，防止行驶中发生爆胎意外。',NULL,'岗位级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(98,'车辆灯光不全，无转向灯、刹车灯',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'每日检查车辆转向灯、刹车灯、大灯、示廓灯，损坏的灯泡及时更换，保证灯光齐全有效，夜间或视线不佳时正常使用灯光警示，确保行车辨识度。',NULL,'岗位级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(99,'车辆电瓶老化鼓包，短路引发火灾',NULL,NULL,3,4,15,180,'橙色','已评审',NULL,'定期检测电瓶电压、外观状态，老化、鼓包、漏液的电瓶立即更换，选用合规合格电瓶产品，充电时做好防火防护，避免电瓶短路、过热起火。',NULL,'公司级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(100,'车辆未定期检修，带病上路行驶',NULL,NULL,3,4,9,108,'黄色','已评审',NULL,'建立车辆专属维保台账，定期开展全面检修保养，排查车辆各项性能隐患，故障问题及时修复，严禁车辆带病上路，保障车辆长期稳定运行安全。',NULL,'部门级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(101,'车辆超员载人，一车多人骑行',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'严格执行一车一人规定，严禁车辆违规载人、载物超员，管理人员日常巡查监督，发现超员行为立即制止，对违规人员依规严肃处理。',NULL,'部门级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(102,'快件超高超宽超载，影响行驶平衡',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'严格限定快件装载高度、宽度及重量，规范对称装载快件，出车前管理人员核查装载情况，杜绝超高、超宽、超载行为，避免影响车辆行驶平衡和操控。',NULL,'部门级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(103,'雨雾天气骑行无防护，视线模糊',NULL,NULL,3,3,7,63,'蓝色','已评审',NULL,'雨雾天气配备专用雨具、防雾镜片，降低行驶速度，开启警示灯光，保持安全车距，视线严重受阻时靠边安全停车，待视线好转后再继续行驶。',NULL,'岗位级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(104,'车辆逆行、随意变道、抢行超车',NULL,NULL,3,6,9,162,'橙色','已评审',NULL,'严格遵守道路交通规则，禁止逆行、随意变道、抢行超车，文明礼让行驶，加强路面监督巡查，对违规行驶行为从严处罚，强化员工规则意识。',NULL,'公司级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(105,'停车未拉手刹，车辆溜车引发事故',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'车辆停放后拉紧手刹，坡道停车额外垫好三角木，下车前再次确认驻车状态，避免因手刹未拉到位、松动导致车辆溜车，引发碰撞事故。',NULL,'岗位级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(106,'充电线路老化，短路引发火灾',NULL,NULL,3,3,15,135,'黄色','已评审',NULL,'选用专用阻燃充电线路，定期检查线路老化、破损情况，问题线路及时更换，采用规范阻燃布线，远离易燃物品，防范充电线路短路起火。',NULL,'部门级',NULL,'网点','车辆管理','2026-07-01 11:52:36'),(107,'室内集中充电无消防防护措施',NULL,NULL,3,3,15,135,'黄色','已评审',NULL,'室内充电区域配备足量灭火器、烟感报警器，保持区域通风干燥，严禁堆放易燃物，充电时安排专人值守，全程做好消防防