输送机运转部位张贴 “禁止靠近”“小心夹手” 标识，每日检查标识完好性，现场管理人员及时制止违规靠近行为，做好安全提醒',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(154,'手持电动打包机电池过度充电，引发鼓包、起火',NULL,NULL,3,4,7,84,'黄色','已评审',NULL,'使用智能充电器，充满自动断电，严禁长时间过度充电，充电时远离易燃物，发现电池鼓包立即更换，做好电池使用台账',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(155,'分拣设备线路杂乱，缠绕、挤压引发短路、起火',NULL,NULL,2,5,8,80,'黄色','已评审',NULL,'整理设备线路，使用理线器固定，穿阻燃套管保护，避免缠绕、挤压，每月检查线路绝缘情况，发现破损立即整改',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(156,'叉车装卸快件时，快件超高超宽，倾倒砸伤人员',NULL,NULL,3,5,9,135,'黄色','已评审',NULL,'严格限定叉车装卸快件高度、宽度，严禁超高超宽，装卸时平稳起升、缓慢行驶，人员远离叉车作业区域，现场专人指挥',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(157,'贴标机压合装置无防护，操作时压伤手指',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'为贴标机压合装置安装防护挡板和感应装置，感应到异物立即停机，每日检查防护、感应装置功能，确保作业安全',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(158,'大型分拣设备未做接地防护，静电引发起火 / 触电',NULL,NULL,2,4,8,64,'蓝色','已评审',NULL,'为大型分拣设备做好可靠接地防护，每月检测接地电阻，确保符合安全标准，在设备周边做好防静电警示',NULL,'转运中心级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(159,'设备维修时未断电、未挂 “禁止合闸” 标识，误操作引发事故',NULL,NULL,3,3,10,90,'黄色','已评审',NULL,'设备维修前必须切断电源，在电源开关处挂 “禁止合闸” 标识，安排专人监护，维修完成后检查设备，确认无隐患再合闸运行',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(160,'小型电动工具（手电钻、切割机）无漏电保护器，使用时触电',NULL,NULL,2,4,7,56,'蓝色','已评审',NULL,'小型电动工具必须安装漏电保护器，每日使用前测试保护器功能，检查工具绝缘情况，破损工具立即停用，严禁无防护使用',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(161,'分拣机快件滑落口无缓冲措施，快件破损 / 人员绊倒',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'在分拣机快件滑落口安装缓冲垫，每日检查缓冲垫完好性，及时清理滑落口堆积快件，确保快件平稳滑落，通道无障碍物',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(162,'传送带速度过快，快件飞出砸伤人员、造成破损',NULL,NULL,2,6,6,72,'黄色','已评审',NULL,'根据快件类型调整传送带速度，严禁超速运行，在传送带两端设置防护栏，防止快件飞出，现场管理人员及时制止违规调速行为',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(163,'电瓶叉车电瓶漏液，腐蚀地面、引发短路',NULL,NULL,2,4,6,48,'蓝色','已评审',NULL,'每日检查电瓶叉车电瓶状态，发现漏液立即停用，清理漏液腐蚀物，对破损电瓶及时更换，充电区做好防渗漏处理',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(164,'设备操作区地面湿滑，操作人员摔倒引发设备误操作',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'及时清理设备操作区地面水渍、油污，铺设防滑垫，设置防滑警示标识，操作人员穿防滑劳保鞋，每日检查地面防滑情况',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(165,'新员工操作设备无人监护，不熟悉流程引发失误 / 事故',NULL,NULL,2,5,7,70,'黄色','已评审',NULL,'新员工操作设备必须有老员工全程监护指导，熟悉操作流程和安全注意事项后，方可独立作业，监护期间做好操作示范和提醒',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(166,'分拣机滚筒磨损、松动，快件卡顿、掉落',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'每月检查分拣机滚筒磨损、松动情况，及时更换磨损滚筒、紧固松动部件，每日清理滚筒间杂物，确保设备平稳运行',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(167,'打包机送带装置故障，胶带回弹打伤人员',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'每日检查打包机送带装置，发现故障立即停机维修，操作时佩戴劳保手套，保持与送带装置安全距离，严禁徒手触碰运行部位',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(168,'叉车后视镜缺失、破损，行驶时观察盲区引发碰撞',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'后视镜缺失、破损立即更换，出车前调整后视镜至最佳视野，行驶时留意周边情况，在盲区路段减速慢行、鸣笛警示',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(169,'自动化分拣系统死机、卡顿，强行重启造成设备损坏',NULL,NULL,1,3,8,24,'蓝色','已评审',NULL,'自动化分拣系统死机后，严禁强行重启，立即联系技术人员处理，做好设备运行记录，定期对系统进行维护、升级，减少故障发生',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(170,'设备润滑油随意存放，沾染快件、引发火灾',NULL,NULL,1,4,6,24,'蓝色','已评审',NULL,'润滑油单独存放在密封容器中，远离明火、快件区域，领用做好登记，加注润滑油时做好防护，避免沾染快件、地面，及时清理洒落润滑油',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(171,'手持扫码设备随意摆放，掉落损坏影响作业',NULL,NULL,2,5,3,30,'蓝色','已评审',NULL,'操作人员手持扫码设备时握紧防滑，放置在固定工位的防滑垫上，避免放在桌边、高台边缘，备用设备定期充电，确保故障时及时替换',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(172,'分拣设备照明不足，操作人员视线受阻引发操作失误',NULL,NULL,2,5,4,40,'蓝色','已评审',NULL,'在设备操作盲区增设照明灯具，损坏灯具 24 小时内更换，保证设备操作区光线充足，夜间作业时全开照明设备，严禁昏暗环境下操作',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(173,'叉车刹车失灵、制动效果不佳，行驶时失控',NULL,NULL,3,6,9,162,'橙色','已评审',NULL,'每日出车前检查叉车刹车系统，定期开展专业维保，刹车失灵、制动效果不佳立即维修，严禁故障叉车上路，培训员工正确刹车操作技巧',NULL,'公司级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(174,'输送机接口处间隙过大，夹伤手指、卡住快件',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'调整输送机接口处间隙，加装防护条，每日检查接口处状态，及时清理卡住的快件，操作人员避免用手触碰接口部位',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(175,'设备运行时操作人员玩手机、注意力不集中，引发事故',NULL,NULL,3,6,3,54,'蓝色','已评审',NULL,'作业期间严禁操作人员玩手机、分心，现场管理人员全程监督，发现分心行为立即制止，将操作专注度纳入员工日常考核',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(176,'分拣区人员过于密集，扎堆作业引发碰撞、摔倒',NULL,NULL,2,7,4,56,'蓝色','已评审',NULL,'划分单人固定作业区域，控制同一区域作业人数，设置人员分流标识，人流高峰时段分批开展分拣作业，严禁推搡、奔跑',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(177,'人工搬运快件姿势不当，弯腰负重引发腰扭伤、肢体拉伤',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'培训员工正确搬运姿势，依靠腿部发力，避免弯腰负重，较重、大件快件安排双人协同搬运，合理控制连续作业时长，每 1 小时休息 10 分钟',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(178,'操作人员未佩戴劳保手套，分拣尖锐快件划伤手部',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'上岗前必须佩戴加厚防滑劳保手套，班组管理人员逐一核查，未佩戴者禁止上岗，及时更换破损、脏污手套，确保防护有效',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(179,'员工长时间低头分拣、扫码，引发颈椎、腰椎不适',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'合理调整分拣工作台、扫码台高度，提醒员工每 30 分钟抬头活动颈椎、起身活动腰椎，安排间歇休息，关注员工职业健康',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(180,'作业区地面散落包装带、纸屑、快件，绊倒操作人员',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'每 30 分钟清理作业区地面散落杂物，保持通道畅通整洁，操作人员行走时留意地面情况，穿防滑劳保鞋，现场设置 “小心绊倒” 标识',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(181,'员工酒后、带病上岗，精神状态不佳引发操作失误',NULL,NULL,3,2,15,90,'黄色','已评审',NULL,'上岗前观察员工精神状态，排查饮酒、带病人员，发现后立即禁止上岗，做好心理疏导和健康关怀，严禁强令员工带病作业',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(182,'操作人员违规攀爬快件堆垛、货架，登高取件引发坠落',NULL,NULL,3,4,8,96,'黄色','已评审',NULL,'严禁攀爬快件堆垛、货架，登高取件使用专用梯架，现场管理人员及时制止攀爬行为，做好安全警示教育，明确违规处罚标准',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(183,'作业区交叉作业，装卸、分拣、运输人员冲突引发事故',NULL,NULL,2,6,6,72,'黄色','已评审',NULL,'划分各作业区域，设置交叉作业警示标识，安排专人现场协调指挥，避免装卸、分拣、运输同时在同一区域作业，确保作业秩序',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(184,'员工在作业区追逐嬉闹、大声喧哗，干扰作业引发意外',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'严禁在作业区追逐嬉闹、大声喧哗，管理人员现场监督制止，加强员工行为规范教育，营造有序作业氛围，违规行为纳入考核',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(185,'夏季高温作业区无通风降温措施，员工中暑',NULL,NULL,3,6,5,90,'黄色','已评审',NULL,'高温时段开启大功率通风、降温设备，为员工提供绿豆汤、藿香正气水等防暑饮品和药品，避开正午高温时段开展高强度作业，设置防暑休息区',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(186,'冬季作业区无保暖措施，员工手脚僵硬引发操作失误',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'作业区配备防爆电暖器，保持室内温度适宜，为员工发放保暖劳保用品，提醒员工作业前做好热身活动，避免手脚僵硬操作',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(187,'快件分拣时误拿尖锐、破损快件，徒手触碰引发划伤',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'分拣时留意快件形状，遇到尖锐、异形、破损快件轻拿轻放，佩戴加厚劳保手套，发现破损尖锐快件单独隔离处理',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(188,'员工连续超时作业，过度疲劳引发注意力不集中、失误',NULL,NULL,3,6,7,126,'黄色','已评审',NULL,'合理安排员工排班，控制每日作业时长，保证员工充足休息，避免连续超负荷作业，发现员工疲劳状态及时安排轮岗休息',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(189,'作业区光线不足，夜间作业视线受阻，引发快件错分、人员受伤',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'在作业区盲区、角落增设照明灯具，损坏灯具及时更换，保证光线充足柔和，夜间作业全开照明设备，严禁昏暗环境下作业',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(190,'操作人员未按规定佩戴安全帽，在货架、设备下方作业被砸伤',NULL,NULL,2,5,7,70,'黄色','已评审',NULL,'在货架、设备下方作业必须佩戴安全帽，班组管理人员现场核查，未佩戴者禁止作业，定期检查安全帽完好性，破损立即更换',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(191,'员工之间因工作争执引发肢体冲突，影响作业、造成伤害',NULL,NULL,1,3,7,21,'蓝色','已评审',NULL,'管理人员第一时间介入调解矛盾，耐心沟通化解分歧，加强员工文明作业教育，避免矛盾激化，营造和谐作业氛围',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(192,'新员工未接受安全培训直接上岗，不熟悉风险引发事故',NULL,NULL,2,4,7,56,'蓝色','已评审',NULL,'新员工入职后先开展岗位安全、操作规范专项培训，覆盖消防、设备、防护等内容，考核合格后方可上岗，安排老员工一对一帮带',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(193,'作业区地面湿滑（水渍、油污、积雪），未设置警示标识',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'及时清理地面水渍、油污、积雪，铺设防滑垫，在周边放置醒目防滑警示标识，待地面完全干燥后再移除防护设施',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(194,'员工操作设备时未按规程操作，违规作业引发设备故障 / 人员受伤',NULL,NULL,2,6,6,72,'黄色','已评审',NULL,'将设备操作规程张贴在作业区显眼位置，培训员工严格按规程操作，管理人员现场监督纠正违规行为，违规者重新培训考核',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(195,'快件搬运时重心不稳，快件倾倒砸伤操作人员',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'搬运快件时保持身体重心平稳，量力而行，避免单手负重、侧身行走，多人协同搬运时配合默契，统一指挥，缓慢移动',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(196,'员工在作业区饮食、喝水，食物残渣、水渍引发地面湿滑 / 设备故障',NULL,NULL,1,6,3,18,'蓝色','已评审',NULL,'严禁在作业区饮食、喝水，设置专用饮水、休息区，每日清理休息区卫生，避免食物残渣、水渍带入作业区，现场管理人员及时制止违规行为',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(197,'分拣快件时暴力抛扔、踩踏，造成快件破损、引发纠纷',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'作业前明确装卸分拣规范，要求轻拿轻放，管理人员全程现场监护，发现抛扔、踩踏行为立即制止，将快件破损率纳入员工考核',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(198,'员工在作业区倚靠设备、快件堆垛，引发设备误操作 / 堆垛倾倒',NULL,NULL,2,5,4,40,'蓝色','已评审',NULL,'严禁倚靠设备、快件堆垛，现场张贴警示标识，管理人员及时提醒制止，加强员工安全意识教育，明确违规行为后果',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(199,'外来人员无登记、无陪同进入作业区，干扰作业、引发意外',NULL,NULL,1,4,7,28,'蓝色','已评审',NULL,'作业区实行封闭式准入管理，外来人员需实名登记、说明来意，由内部人员全程陪同进入指定区域，严禁无关人员穿行作业区',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(200,'员工未掌握岗位应急处置方法，突发情况时慌乱失措',NULL,NULL,2,3,7,42,'蓝色','已评审',NULL,'制作岗位风险告知卡，明确应急处置方法，张贴在作业区显眼处，每月开展应急处置培训，结合案例讲解突发情况应对技巧',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(201,'作业区噪音过大，员工听力受损、沟通不畅引发失误',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'为员工发放隔音耳塞，在高噪音设备周边设置隔音屏障，定期检测作业区噪音值，控制在安全标准范围内，优化设备布局减少噪音叠加',NULL,'转运中心级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(202,'员工擅自离岗、脱岗，作业岗位无人值守引发快件错分、丢失',NULL,NULL,2,4,5,40,'蓝色','已评审',NULL,'严格执行岗位考勤制度，员工离岗需报备并找人顶岗，严禁擅自离岗、脱岗，管理人员定时巡查岗位值守情况，违规者依规处理',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(203,'操作人员使用胶带切割机时操作不当，割伤手指',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'操作时保持手指与刀片安全距离，缓慢拉动胶带，刀片钝化后及时更换专用刀片，不用时将刀片收回防护壳内，规范存放设备',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(204,'员工在作业区穿拖鞋、高跟鞋、宽松衣物，引发绊倒、夹伤',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'上岗前必须穿防滑劳保鞋、紧身作业服，严禁穿拖鞋、高跟鞋、宽松衣物，班组管理人员逐一核查，未按规定着装者禁止上岗',NULL,'岗位级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(205,'多人协同作业时无统一指挥，配合失误引发人员受伤、快件破损',NULL,NULL,2,5,5,50,'蓝色','已评审',NULL,'多人协同作业时指定专人统一指挥，明确分工和操作流程，作业前做好沟通确认，避免配合失误，现场管理人员做好协调监督',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(206,'快件无序堆放，混堆混放引发错分、丢失、破损',NULL,NULL,2,7,4,56,'蓝色','已评审',NULL,'按目的地、品类划分快件堆放区域，设置清晰标识，分拣后及时将快件归置对应区域，严禁混堆混放，每日核查堆放情况',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(207,'液体快件未单独分区存放，破损泄漏污染其他快件 / 地面',NULL,NULL,2,6,7,84,'黄色','已评审',NULL,'液体快件单独存放在防渗漏区域，采用防挤压、防渗漏包装，单独分拣、搬运，发生泄漏后立即转移至通风区域，用专用吸附材料清理',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(208,'易碎品快件未做特殊标注、防护，分拣搬运时破损',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'提醒客户对易碎品做好防碎包装，粘贴醒目易碎标识，易碎品单独分拣、轻拿轻放，严禁堆叠挤压，配备专用防护缓冲材料',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(209,'快件堆放过高、重心不稳，发生倾倒砸伤人员、造成破损',NULL,NULL,2,7,5,70,'黄色','已评审',NULL,'严格限定快件堆放高度，遵循下重上轻原则，底部铺垫稳固托盘，避免单侧倾斜，人员不在高堆快件下方停留、作业',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(210,'快件错分、错发，引发客户投诉、服务纠纷',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'分拣时仔细核对快件目的地、收件人信息，扫码确认后再归置，快件交接时双方签字核对数量和信息，完善流转记录，错分后及时溯源整改',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(211,'快件包装破损未及时处理，导致内件丢失、污染',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'分拣时发现破损快件立即停止流转，使用专用包装材料重新封装，登记破损信息，核对内件完整性，单独存放并及时上报处理',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(212,'高价值快件未单独存放、无防护，引发丢失、被盗',NULL,NULL,3,4,10,120,'黄色','已评审',NULL,'高价值快件单独存放在带锁储物柜中，实行双人双锁管理，分拣、搬运全程专人跟进，做好登记记录，确保全程可控',NULL,'转运中心级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(213,'易燃易爆违禁品未检出，流入作业区引发火灾、爆炸',NULL,NULL,4,3,20,240,'橙色','已评审',NULL,'严格执行开箱验视、实名收寄制度，对粉末、液体、异形包装快件重点核查，配备安检设备，每日对快件进行安检，发现违禁品立即暂扣上报',NULL,'公司级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(214,'生鲜快件未做冷藏防护，堆放时间过长引发变质',NULL,NULL,2,5,6,60,'蓝色','已评审',NULL,'生鲜快件单独存放在冷藏区域，控制存放温度和时间，优先分拣、派送，配备专用冷藏运输设备，确保生鲜快件新鲜度',NULL,'部门级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(215,'快件上的客户隐私信息（姓名、电话、地址）外露，引发泄露',NULL,NULL,1,6,7,42,'蓝色','已评审',NULL,'对快件上的隐私信息进行模糊处理，严禁员工拍摄、转发、传播客户信息，全员签订信息保密协议，泄露信息依规严肃处理',NULL,'转运中心级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(216,'大件、超重快件未单独搬运，引发快件破损、人员受伤',NULL,NULL,2,5,6,60,'蓝色','已评审',NULL,'大件、超重快件单独存放，安排双人或使用工具协同搬运，严禁单人搬运，搬运时做好防护，避免快件破损、人员拉伤',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(217,'快件交接时无记录、无核对，引发数量不符、责任不清',NULL,NULL,1,6,5,30,'蓝色','已评审',NULL,'建立规范的快件交接台账，交接时双方当面核对快件数量、信息，签字确认，确保账物相符，出现问题及时溯源，明确责任',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(218,'废弃快件、包装未及时清理，堆积占用场地、引发隐私泄露',NULL,NULL,1,6,3,18,'蓝色','已评审',NULL,'设置废弃快件、包装专用回收箱，每日清理，废弃快件做隐私信息销毁处理后再回收，严禁随意丢弃，做好回收记录',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(219,'快件被雨水、积雪浸湿，导致内件受潮、破损',NULL,NULL,2,5,4,40,'蓝色','已评审',NULL,'在作业区入口、快件堆放区设置防雨、防雪设施，及时清理浸湿快件，用干布擦拭、通风晾干，对受潮破损快件及时上报处理',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(220,'分拣时快件掉入设备间隙，造成设备故障、快件丢失',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'清理设备间隙杂物，在设备周边设置防护栏，防止快件掉入，发现快件掉入后立即停机，用专用工具取出，严禁开机取件',NULL,'班组级',NULL,'转运中心','作业现场','2026-07-01 11:52:36'),(221,'假冒