NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'厨师操作时必须穿防滑劳保鞋、紧身工作服，严禁穿拖鞋、宽松衣物，管理员每日检查着装情况，未按规定者禁止上岗',NULL,'岗位级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(290,'食堂就餐高峰人员过于密集，扎堆打饭引发碰撞、摔倒',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'就餐高峰安排专人疏导，设置打饭排队标识，划分就餐区域，引导员工有序打饭、就餐，避免扎堆拥挤，及时清理地面水渍',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(291,'食堂外来人员无登记进入操作区，干扰作业、引发卫生 / 安全隐患',NULL,NULL,1,4,7,28,'蓝色','已评审',NULL,'食堂操作区实行封闭式管理，外来人员禁止进入，就餐区外来人员需实名登记，由员工陪同，管理员做好人员进出管理，及时制止违规进入行为',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(292,'食堂员工酒后、带病上岗，精神状态不佳引发操作失误 / 食品污染',NULL,NULL,2,4,7,56,'蓝色','已评审',NULL,'上岗前观察员工精神状态，排查饮酒、带病人员，发现后立即禁止上岗，做好健康关怀，严禁强令员工带病作业，确保食品加工安全',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(293,'食堂地面油污、水渍未及时清理，铺设防滑垫，人员滑倒',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'及时清理地面油污、水渍，使用专用除油剂，铺设防滑垫，设置防滑警示标识，员工穿防滑劳保鞋，管理员每日检查地面防滑情况',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(294,'食堂食材、厨具堆放过高、杂乱，引发倾倒、砸伤人员',NULL,NULL,2,5,4,40,'蓝色','已评审',NULL,'食材、厨具按规定高度堆放，遵循下重上轻原则，整齐归置，严禁杂乱堆放，管理员每日核查堆放情况，及时整改违规堆放行为',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(295,'食堂未按规定开展卫生检查，隐患未及时发现、整改',NULL,NULL,2,4,6,48,'蓝色','已评审',NULL,'制定食堂卫生安全每日、每周、每月检查制度，建立检查台账，对发现的隐患立即整改，明确整改责任人、时限，做好整改复查记录',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(296,'食堂厨房燃气灶、蒸箱故障，漏气、漏水引发事故 / 操作失误',NULL,NULL,2,6,8,96,'黄色','已评审',NULL,'每日检查燃气灶、蒸箱运行状态，发现漏气、漏水立即停用，由专业人员维修，做好设备维保台账，定期开展专业维保',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(297,'食堂厨房刀具、厨具随意摆放，引发划伤、割伤人员',NULL,NULL,2,7,3,42,'蓝色','已评审',NULL,'刀具、厨具定点存放，设置专用刀具架，做到刀架分离，使用后及时归位，严禁随意摆放，提醒员工使用刀具时注意安全，佩戴防护手套',NULL,'岗位级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(298,'食堂电蒸箱、电烤箱未做接地防护，漏电引发触电',NULL,NULL,2,5,7,70,'黄色','已评审',NULL,'为电蒸箱、电烤箱做好可靠接地防护，每月检测接地电阻，每日使用前检查设备绝缘情况，发现漏电立即停用，由专业人员维修',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(299,'食堂餐桌、餐椅破损、松动，人员就餐时摔倒、划伤',NULL,NULL,2,6,3,36,'蓝色','已评审',NULL,'定期检查餐桌、餐椅完好性，破损、松动及时维修更换，对暂时无法修补的设置警示标识，提醒员工注意安全，做好日常维护',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(300,'食堂厨房洗菜池、排水沟堵塞，积水、油污堆积引发地面湿滑',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'每日清洁洗菜池、排水沟，及时清理堵塞物，定期疏通排水沟，在地面铺设防滑垫，设置防滑警示标识，及时清理积水、油污',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(301,'食堂抽油烟机故障，油烟无法排出，影响操作、引发人员不适',NULL,NULL,2,5,6,60,'蓝色','已评审',NULL,'每日检查抽油烟机运行状态，发现故障立即停用维修，定期清洁滤网、扇叶，保证油烟正常排出，做好设备清洁和维保记录',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(302,'食堂厨房冰柜、冷藏柜温度失控，食材变质、损坏',NULL,NULL,2,5,7,70,'黄色','已评审',NULL,'每日检查冰柜、冷藏柜温度，做好温度记录，温度失控立即停用，转移食材，由专业人员维修，定期校准温度控制装置',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(303,'食堂内照明灯具破损、油污堆积，影响视线、引发触电',NULL,NULL,2,5,4,40,'蓝色','已评审',NULL,'及时更换破损灯具，定期清洁灯具上的油污，保证照明亮度，在厨房、就餐区合理布设灯具，消除照明盲区，做好灯具日常维护',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(304,'食堂厨房推车、置物架破损、松动，倾倒砸伤人员、污染食材',NULL,NULL,2,5,5,50,'蓝色','已评审',NULL,'定期检查推车、置物架完好性，破损、松动及时维修加固，限定置物架承重，严禁超载堆放，推车使用时平稳推行，避免急停、急转弯',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(305,'食堂洗碗池、消毒柜破损，漏水、消毒失效引发卫生问题',NULL,NULL,2,5,6,60,'蓝色','已评审',NULL,'每日检查洗碗池、消毒柜运行状态，发现漏水、消毒失效立即停用维修，做好设备维保记录，确保洗碗、消毒功能正常',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(306,'食堂采购食材变质、过期、三无产品，引发员工食物中毒',NULL,NULL,4,6,15,360,'红色','已评审',NULL,'建立食材采购溯源台账，选择合格供应商，采购时查验食材保质期、合格证，严禁采购变质、过期、三无产品，做好食材验收记录',NULL,'公司级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(307,'食堂食材未按规定储存，生熟混放、交叉污染',NULL,NULL,3,7,8,168,'橙色','已评审',NULL,'食材按生熟、荤素分区存放，生肉、蔬菜、熟食单独冷藏，冷藏温度控制在0-4℃，冷冻温度≤-18℃，每日检查食材储存情况，及时清理变质食材',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(308,'食堂餐具未按规定消毒，滋生细菌、引发肠胃疾病',NULL,NULL,2,7,7,98,'黄色','已评审',NULL,'餐具按“一洗、二清、三消毒、四保洁”流程处理，消毒后存放于保洁柜，每日检测餐具消毒效果，做好消毒记录，确保消毒达标',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(309,'食堂厨师未持健康证上岗，患有传染性疾病，传播病菌',NULL,NULL,3,6,9,162,'橙色','已评审',NULL,'食堂从业人员必须持有效健康证上岗，每年体检1次，发现患有传染性疾病立即调离岗位，建立从业人员健康台账，每日检查上岗状态',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(310,'食堂厨房操作台面、厨具未及时清洁，油污、食物残渣堆积',NULL,NULL,2,7,6,84,'黄色','已评审',NULL,'每日清洁操作台面、厨具，及时清除油污、食物残渣，定期消毒，制定厨房卫生值日表，管理员每日检查，确保操作区域干净整洁',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(311,'食堂就餐区餐桌、地面未及时清洁，食物残渣、水渍堆积',NULL,NULL,1,7,4,28,'蓝色','已评审',NULL,'就餐结束后及时清洁餐桌、地面，清除食物残渣、水渍，定时对就餐区消毒，设置垃圾桶，引导员工规范丢弃垃圾，保持就餐区整洁',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(312,'食堂食材清洗不彻底，残留农药、泥沙，引发肠胃不适',NULL,NULL,2,6,6,72,'黄色','已评审',NULL,'食材分类清洗，蔬菜浸泡15分钟后冲洗干净，肉类、水产单独清洗，避免交叉污染，清洗后沥干水分再加工，管理员做好操作监督',NULL,'岗位级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(313,'食堂食品加工未烧熟煮透，生熟刀具、砧板混用',NULL,NULL,3,6,8,144,'黄色','已评审',NULL,'食品加工必须烧熟煮透，中心温度≥70℃，生熟刀具、砧板、容器分开使用并做好标识，定期消毒，管理员现场监督加工过程',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(314,'食堂剩余饭菜未按规定冷藏，再次食用前未彻底加热',NULL,NULL,2,5,7,70,'黄色','已评审',NULL,'剩余饭菜及时冷藏，冷藏时间≤24小时，再次食用前彻底加热至中心温度≥70℃，对隔夜饭菜做好标识，超过时限立即丢弃',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(315,'食堂内苍蝇、蚊虫、老鼠滋生，污染食材、餐具',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'每周对食堂开展1次全面消杀，安装防蝇帘、灭蚊灯、防鼠板，及时清理食物残渣、积水，保持食堂卫生，做好消杀记录',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(316,'食堂饮用水未达标，水质浑浊、有异味，引发肠胃疾病',NULL,NULL,2,7,7,98,'黄色','已评审',NULL,'定期检测饮用水水质，确保符合国家饮用水标准，每日清洁饮水机、储水设备，定期消毒，做好水质检测和设备清洁记录',NULL,'转运中心级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(317,'食堂厨师操作时未穿戴工作衣帽、口罩，个人卫生差',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'厨师操作时必须穿戴干净的工作衣帽、口罩，勤洗手、剪指甲，严禁留长指甲、戴首饰，管理员每日检查个人卫生情况，未按规定者禁止上岗',NULL,'岗位级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(318,'食堂采购的散装食品无标识、无保质期，引发食品安全风险',NULL,NULL,2,5,7,70,'黄色','已评审',NULL,'严禁采购无标识、无保质期的散装食品，采购散装食品需查验供应商资质，做好采购记录，对散装食品做好标识，注明名称、保质期',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(319,'食堂厨房垃圾桶未加盖、未及时清理，滋生细菌、散发异味',NULL,NULL,1,7,4,28,'蓝色','已评审',NULL,'厨房垃圾桶必须加盖，做到日产日清，及时清理厨余垃圾，定期对垃圾桶消毒，设置垃圾分类标识，引导员工规范丢弃垃圾',NULL,'班组级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(320,'食堂食品添加剂未按规定使用，超量、超范围添加',NULL,NULL,3,4,10,120,'黄色','已评审',NULL,'食品添加剂专人管理、专柜存放，做好领用登记，严格按国家标准限量使用，严禁超量、超范围添加，管理员定期检查添加剂使用情况',NULL,'部门级',NULL,'转运中心','食堂','2026-07-01 11:52:36'),(321,'驾驶员超速行驶，超过道路限速标准或公司规定速度',NULL,NULL,4,8,9,288,'橙色','已评审',NULL,'为所有车辆加装限速装置，限定最高行驶速度，通过 GPS 实时监控车速，每月通报超速行为，对违规者处以停岗培训、绩效扣分处罚',NULL,'车队级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(322,'闯红灯、逆行、不按导向车道行驶等违反交通信号行为',NULL,NULL,3,7,9,189,'橙色','已评审',NULL,'每月开展交通安全法规培训，结合典型事故案例强化规则意识，在车辆仪表盘张贴交通规则提示卡，GPS 监控违规行为并严肃追责',NULL,'公司级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(323,'驾驶员疲劳驾驶，连续驾驶超过 4 小时未休息',NULL,NULL,4,6,10,240,'橙色','已评审',NULL,'建立驾驶时长台账，强制要求连续驾驶 4 小时休息不少于 20 分钟，GPS 实时监测行驶时长，发现疲劳驾驶迹象立即提醒并要求停车休息',NULL,'车队级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(324,'行车中使用手机、接打电话、分心驾驶',NULL,NULL,3,8,7,168,'橙色','已评审',NULL,'安装手机使用屏蔽装置，驾驶位张贴 “禁玩手机” 标识，通过车内监控监督驾驶行为，发现分心驾驶立即通报批评并纳入考核',NULL,'班组级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(325,'强行超车、加塞，违反让行规定引发剐蹭碰撞',NULL,NULL,3,6,8,144,'黄色','已评审',NULL,'培训文明驾驶技巧，强调安全车距保持要求，通过行车记录仪核查违规超车行为，对多次违规者暂停上岗资格',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(326,'驾驶员酒后、吸毒后驾驶车辆',NULL,NULL,5,2,40,400,'红色','已评审',NULL,'建立岗前酒精检测制度，每日出车前进行酒精测试，发现酒后驾驶立即开除并移交司法部门，签订拒绝酒驾承诺书',NULL,'公司级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(327,'夜间行车未按规定使用灯光，或滥用远光灯',NULL,NULL,2,7,6,84,'黄色','已评审',NULL,'培训夜间灯光使用规范，在车辆灯光控制区张贴使用说明，通过行车记录仪抽查灯光使用情况，违规者进行专项培训',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(328,'在路口、学校、居民区等区域未减速慢行',NULL,NULL,3,7,6,126,'黄色','已评审',NULL,'设置车速提醒标识，GPS 定位重点区域并自动提醒减速，要求重点区域车速不超过 30km/h，定期核查行车数据',NULL,'班组级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(329,'驾驶员开车时吸烟、饮食、与人打闹影响操作',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'车内张贴禁止吸烟、饮食标识，驾驶员签订安全驾驶承诺书，同行人员监督提醒，发现违规行为纳入日常考核',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(330,'雨雪雾等恶劣天气未降低车速，未做好防滑措施',NULL,NULL,3,5,9,135,'黄色','已评审',NULL,'恶劣天气前发布预警通知，要求降低车速 30% 以上，配备防滑链、三角警示牌等设备，严禁在能见度低于 50 米时强行行驶',NULL,'车队级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(331,'超载、超员行驶，超出车辆核定载重量或载客人数',NULL,NULL,3,6,10,180,'橙色','已评审',NULL,'安装载重监测装置，严禁快件装载超过核定重量，明确一人一车规定，严禁违规载人，定期核查车辆装载情况',NULL,'公司级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(332,'驾驶员未按规定让行行人、非机动车，引发事故',NULL,NULL,2,7,7,98,'黄色','已评审',NULL,'加强行人安全防护培训，强调 “车让人” 原则，通过行车记录仪检查让行情况，对未按规定让行的行为进行处罚',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(333,'在高速公路违规停车、倒车、逆行等危险行为',NULL,NULL,4,3,15,180,'橙色','已评审',NULL,'开展高速公路安全驾驶专项培训，明确禁止危险行为，GPS 实时监控高速行驶轨迹，发现违规立即叫停并严肃处理',NULL,'公司级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(334,'驾驶员故意遮挡、污损机动车号牌',NULL,NULL,2,2,15,60,'蓝色','已评审',NULL,'定期检查车辆号牌完整性，要求驾驶员保持号牌清晰，严禁遮挡、污损行为，发现后立即整改并处罚',NULL,'公司级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(335,'强行通过积水、塌方、施工路段，未观察路况',NULL,NULL,3,4,8,96,'黄色','已评审',NULL,'培训复杂路况通行技巧，要求通过危险路段前停车观察，配备路况查询工具，严禁盲目强行通过危险区域',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(336,'刹车系统失灵、制动距离过长，制动效果不佳',NULL,NULL,4,7,10,280,'橙色','已评审',NULL,'每日出车前检查刹车系统，每周开展专业制动检测，每月进行刹车系统维保，发现制动异常立即停用维修',NULL,'车队级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(337,'轮胎磨损过度、鼓包、漏气，未及时更换',NULL,NULL,3,8,7,168,'橙色','已评审',NULL,'每日出车前检查轮胎胎压、磨损情况，建立轮胎更换台账，磨损达到极限值立即更换，严禁使用故障轮胎行驶',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(338,'转向系统故障，方向盘卡顿、跑偏，操控失灵',NULL,NULL,3,6,10,180,'橙色','已评审',NULL,'定期检查转向系统间隙、助力油液位，每月进行转向系统校准，发现方向盘卡顿、跑偏立即停车维修',NULL,'车队级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(339,'灯光系统故障，大灯、转向灯、刹车灯不亮或闪烁',NULL,NULL,2,7,6,84,'黄色','已评审',NULL,'每日出车前核查所有灯光功能，损坏灯具 24 小时内更换，定期清洁灯罩，确保夜间行驶灯光亮度充足',NULL,'班组级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(340,'电瓶老化、鼓包、漏液，无法正常启动或引发起火',NULL,NULL,3,5,8,120,'黄色','已评审',NULL,'定期检测电瓶电压、外观状态，老化鼓包电瓶立即更换，使用合规电瓶产品，充电时做好防火防护',NULL,'部门级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(341,'车辆油路泄漏、燃油不足，引发火灾或半路熄火',NULL,NULL,3,4,10,120,'黄色','已评审',NULL,'每周检查油路管道、接口密封性，每日出车前确认燃油量，发现泄漏立即维修，严禁燃油不足时强行行驶',NULL,'车队级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(342,'冷却系统故障，水箱漏水、水温过高，发动机过热',NULL,NULL,2,5,7,70,'黄色','已评审',NULL,'定期检查冷却系统水位、散热风扇功能，清理水箱杂物，发现水温异常立即停车降温，避免发动机损坏',NULL,'班组级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(343,'喇叭、雨刮器故障，无法警示或清洁视线',NULL,NULL,2,6,4,48,'蓝色','已评审',NULL,'每日出车前测试喇叭音量、雨刮器效果，损坏部件及时更换，确保恶劣天气视线清晰、警示功能正常',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(344,'安全带破损、卡扣失灵，无法起到防护作用',NULL,NULL,2,7,5,70,'黄色','已评审',NULL,'每日检查安全带完好性，破损、失灵的立即更换，要求驾驶员及乘客全程系好安全带，纳入出车前核查项',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(345,'后视镜缺失、破损、调节失灵，影响观察视野',NULL,NULL,2,8,4,64,'蓝色','已评审',NULL,'后视镜缺失、破损立即更换，出车前调节至最佳视野，定期检查后视镜固定情况，确保行车观察无盲区',NULL,'岗位级',NULL,'车队','车辆运行安全','2026-07-01 11:52:36'),(346,'车窗玻璃破损、模糊，影响驾驶视线',NULL,NULL,2,6,5,60,'蓝色','已评审',NULL,'及时更换破损车窗玻璃，定期清洁玻璃污渍，